#!/usr/bin/env bash
# Enforce Conventional Commits on the message (pre-commit `commit-msg` stage).
#
#   feat(scan): add SARIF export
#   fix(auth): reject expired refresh tokens
#
# Types: feat fix docs style refactor perf test build ci chore revert
set -uo pipefail

MESSAGE_FILE="${1:-}"
[ -n "$MESSAGE_FILE" ] && [ -f "$MESSAGE_FILE" ] || exit 0

FIRST_LINE=$(head -n 1 "$MESSAGE_FILE" | tr -d '\r')

# Allow merge/revert/fixup messages and comments generated by git.
case "$FIRST_LINE" in
  "Merge "*|"Revert "*|"fixup! "*|"squash! "*|"") exit 0 ;;
esac

PATTERN='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([a-z0-9._/-]+\))?!?: .{3,}'

if ! printf '%s' "$FIRST_LINE" | grep -qE "$PATTERN"; then
  cat >&2 <<EOF
✖ Commit message does not follow Conventional Commits.

  got:  $FIRST_LINE
  want: <type>(<scope>): <summary>

  types: feat fix docs style refactor perf test build ci chore revert
  e.g.:  feat(scans): export findings as SARIF
EOF
  exit 1
fi

if [ "${#FIRST_LINE}" -gt 100 ]; then
  echo "✖ Commit subject is ${#FIRST_LINE} characters — keep it under 100." >&2
  exit 1
fi
